  const TWO = (a, b) => `forever{ if:L=1{ run:L,fwd,${b} run:R,fwd,${a} } else{ if:R=1{ run:L,fwd,${a} run:R,fwd,${b} } else{ run:all,fwd,${a} } } }`;
